<script lang="ts">
  import { invoke } from '@tauri-apps/api/core';
  import { locale } from './i18n';
  import { onMount } from 'svelte';
  import UiIcon from './UiIcon.svelte';
  let { username, oninstallations = () => {} }: { username:string; oninstallations?:()=>void } = $props();
  type Target={id:string;name:string;version_id:string;pack_id:string|null;installed:boolean;fabric_api:boolean;companion:boolean;mode:string};
  type Workspace={artifact_available:boolean;version:string;minecraft:string;loader:string;java:number;targets:Target[]};
  let workspace=$state<Workspace|null>(null), selected=$state(''), mode=$state('minimal');
  let replaceCompanion=$state(false), installApi=$state(true), restorePrevious=$state(false);
  let loading=$state(true), busy=$state(false), error=$state(''), message=$state('');
  let target=$derived(workspace?.targets.find(row=>row.id===selected));
  let english=$derived(!$locale.startsWith('es'));
  const text=(es:string,en:string)=>english?en:es;
  let sequence=0;
  async function refresh(){const request=++sequence;loading=true;error='';try{const value=await invoke<Workspace>('tp_client_workspace',{username});if(request!==sequence)return;workspace=value;if(!value.targets.some(row=>row.id===selected)){selected=value.targets[0]?.id??'';mode=value.targets[0]?.mode==='full'?'full':'minimal';}}catch(problem){if(request===sequence)error=String(problem);}finally{if(request===sequence)loading=false;}}
  function choose(){mode=target?.mode==='full'?'full':'minimal';replaceCompanion=false;message='';}
  async function install(){if(!target||busy)return;busy=true;error='';message=text('Verificando y preparando TP Client…','Verifying and preparing TP Client…');try{const result=await invoke<string>('tp_client_install',{username,versionId:target.version_id,packId:target.pack_id,mode,replaceCompanion,installFabricApi:installApi});await refresh();message=result;}catch(problem){message='';error=String(problem);}finally{busy=false;}}
  async function remove(){if(!target||busy)return;busy=true;error='';message='';try{const result=await invoke<string>('tp_client_remove',{username,versionId:target.version_id,packId:target.pack_id,restorePrevious});await refresh();message=result;}catch(problem){error=String(problem);}finally{busy=false;}}
  onMount(()=>{void refresh();return()=>{sequence++;};});
</script>

<section class="tp-client-panel" aria-busy={busy||loading}>
  <header><div class="identity"><span class="client-emblem"><UiIcon name="plugins" size={28}/></span><div><small>TP LABS · CLIENT MOD</small><h2>TP Client</h2><p>{text('Tu HUD dentro de Minecraft. Tu diseño. Tus reglas.','Your HUD inside Minecraft. Your layout. Your rules.')}</p></div></div><span class="compatibility">Fabric · 1.21.1 · Java 21</span></header>
  <div class="client-summary"><div><UiIcon name="monitor" size={21}/><strong>{text('Renderizado en el juego','Rendered in game')}</strong><p>{text('Menú con Shift derecho, métricas reales y edición de widgets, también en pantalla completa.','Right Shift menu, real metrics and editable widgets, including full-screen mode.')}</p></div><div><UiIcon name="shield" size={21}/><strong>{text('Instalación voluntaria','Opt-in installation')}</strong><p>{text('Solo en instalaciones compatibles. No convierte Vanilla ni modifica tus mundos.','Only in compatible installations. No Vanilla conversion or world changes.')}</p></div><div><UiIcon name="sliders" size={21}/><strong>{text('Ajustes independientes','Independent settings')}</strong><p>{text('El diseño y los cosméticos locales permanecen disponibles sin el launcher abierto.','Layout and local cosmetics remain available when the launcher is closed.')}</p></div></div>
  {#if loading}<p class="notice" role="status">{text('Revisando instalaciones compatibles…','Checking compatible installations…')}</p>{/if}
  {#if workspace&&!workspace.artifact_available}<p class="notice">{text('Esta compilación aún no incluye un JAR de TP Client con su huella verificada. No se instalarán archivos sin verificar.','This build does not yet contain a verified TP Client JAR. Unverified files will not be installed.')}</p>{/if}
  {#if workspace&&workspace.targets.length}
    <div class="client-controls"><label>{text('Instalación de destino','Target installation')}<select bind:value={selected} onchange={choose} disabled={busy||loading}>{#each workspace.targets as row}<option value={row.id}>{row.name}{row.pack_id?' · Modpack':''}{row.installed?' · TP Client':''}</option>{/each}</select></label><label>{text('Contenido del cliente','Client features')}<select bind:value={mode} disabled={busy||loading}><option value="minimal">{text('Mínimo · HUD y herramientas esenciales','Minimal · HUD and essentials')}</option><option value="full">{text('Completo · HUD y cosméticos TP locales','Full · HUD and local TP cosmetics')}</option></select></label></div>
    {#if target}<div class="target-status"><span class:ready={target.installed}><UiIcon name={target.installed?'check':'download'} size={15}/>{target.installed?text('TP Client instalado','TP Client installed'):text('Sin TP Client','TP Client not installed')}</span><span class:ready={target.fabric_api}><UiIcon name="layers" size={15}/>Fabric API · {target.fabric_api?text('Disponible','Available'):text('Requerida','Required')}</span></div>
      {#if !target.fabric_api}<label class="permission"><input type="checkbox" bind:checked={installApi} disabled={busy}/><span>{text('Instalar Fabric API compatible desde Modrinth, verificando su descarga. Se conserva al retirar TP Client porque otros mods pueden necesitarla.','Install compatible Fabric API from Modrinth with download verification. It is retained after removing TP Client because other mods may need it.')}</span></label>{/if}
      {#if target.companion}<label class="permission warning"><input type="checkbox" bind:checked={replaceCompanion} disabled={busy}/><span>{text('Sustituir TP Companion por TP Client en esta instancia. Se guarda un respaldo para restaurarlo al desinstalar.','Replace TP Companion with TP Client in this instance. A backup is retained for restoration when uninstalling.')}</span></label>{/if}
      <div class="actions"><button class="primary" onclick={install} disabled={busy||loading||!workspace.artifact_available||(target.companion&&!replaceCompanion)||(!target.fabric_api&&!installApi)}><UiIcon name="download" size={17}/>{busy?text('Aplicando…','Applying…'):target.installed?text('Aplicar modo seleccionado','Apply selected mode'):text('Instalar TP Client','Install TP Client')}</button><button onclick={refresh} disabled={busy||loading}><UiIcon name="refresh" size={16}/>{text('Actualizar','Refresh')}</button>{#if target.installed}<button class="remove" onclick={remove} disabled={busy||loading}><UiIcon name="trash" size={16}/>{text('Desinstalar TP Client','Uninstall TP Client')}</button>{/if}</div>
      {#if target.installed}<label class="permission"><input type="checkbox" bind:checked={restorePrevious} disabled={busy}/><span>{text('Al desinstalar, restaurar la configuración previa y TP Companion si fue sustituido.','When uninstalling, restore previous settings and TP Companion if it was replaced.')}</span></label>{/if}
    {/if}
  {:else if !loading&&workspace}<div class="empty"><UiIcon name="folder" size={29}/><h3>{text('Prepara una instalación Fabric 1.21.1','Prepare a Fabric 1.21.1 installation')}</h3><p>{text('La primera versión de TP Client requiere Fabric 1.21.1. Tus versiones Vanilla, Forge, OptiFine y otras versiones de Fabric se conservan.','The first TP Client release requires Fabric 1.21.1. Your Vanilla, Forge, OptiFine and other Fabric versions are preserved.')}</p><button onclick={oninstallations}><UiIcon name="grid" size={16}/>{text('Abrir instalaciones','Open installations')}</button></div>{/if}
  {#if message}<p class="notice success" role="status">{message}</p>{/if}{#if error}<p class="notice warning" role="alert">{error}</p>{/if}
  <footer><UiIcon name="info" size={16}/><span>{text('TP Client y el overlay de escritorio son sistemas distintos. No se promete compatibilidad con versiones que aún no tienen un adaptador compilado. Los cosméticos TP son locales y no desbloquean capas oficiales.','TP Client and the desktop overlay are separate systems. Compatibility is limited to compiled adapters. TP cosmetics are local and do not unlock official capes.')}</span></footer>
</section>

<style>
 .tp-client-panel{display:grid;gap:20px;padding:26px;margin-bottom:26px;background:linear-gradient(120deg,#17121fef,#0d0d12f2);border:1px solid #a855f750;color:#eee6f7;min-width:0}.tp-client-panel header,.identity,.actions,.target-status{display:flex;align-items:center;gap:15px;flex-wrap:wrap}.tp-client-panel header{justify-content:space-between}.identity{flex-wrap:nowrap}.client-emblem{display:grid;place-items:center;width:58px;height:58px;background:#b67bf013;border:1px solid #a855f749;flex-shrink:0}.identity small{font-size:10px;letter-spacing:.16em;color:#bca6d1}.identity h2{margin:6px 0;font-size:27px;font-weight:750}.identity p,.client-summary p,.empty p{margin:0;color:#b5a8c1;font-size:12px;line-height:1.7}.compatibility{padding:9px 12px;font-size:11px;color:#d8c5e8;border:1px solid #ffffff23;white-space:nowrap}.client-summary{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}.client-summary>div{display:grid;grid-template-columns:22px 1fr;align-items:center;gap:9px;padding:16px;border:1px solid #ffffff12;background:#ffffff03}.client-summary strong{font-size:12px}.client-summary p{grid-column:1/-1;font-size:11px}.client-summary :global(svg){color:#c1a2e4}.client-controls{display:grid;grid-template-columns:minmax(0,1.3fr) minmax(0,1fr);gap:16px}.client-controls label{display:grid;gap:9px;font-size:12px;color:#c7b8d5}.client-controls select{width:100%;min-width:0;padding:13px;border:1px solid #ffffff25;background:#101019;color:#eee6f7;font:inherit;color-scheme:dark}.target-status{font-size:11px;gap:10px}.target-status>span{display:flex;align-items:center;gap:7px;padding:8px 11px;border:1px solid #ffffff1f;color:#b6a7c3}.target-status .ready{color:#a4d7bd;border-color:#78b79840}.permission{display:flex;align-items:flex-start;gap:10px;font-size:11px;color:#b6a7c5;line-height:1.7}.permission input{margin-top:4px;accent-color:#a855f7;flex-shrink:0}button{display:inline-flex;align-items:center;justify-content:center;gap:8px;background:#ffffff06;color:#e0d2ed;font:inherit;font-size:12px;border:1px solid #ffffff29;padding:12px 16px;cursor:pointer}button.primary{background:#a855f72a;border-color:#a855f780;color:#f1deff;font-weight:650}button.remove{margin-left:auto;color:#d9b8c0}button:hover:not(:disabled){background:#a855f727;border-color:#bb8ce8}button:disabled{opacity:.4;cursor:default}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid #d2a1fc;outline-offset:3px}.notice{padding:13px 16px;border:1px solid #ffffff26;color:#c9b9d9;font-size:12px;line-height:1.7;margin:0}.notice.success{color:#b6dec8;border-color:#79bc9b55;background:#79bc9b08}.warning{color:#e0c4a1}.notice.warning{border-color:#d5ad6550;background:#d5ad6509}.empty{padding:22px;border:1px dashed #ffffff24;display:grid;justify-items:start;gap:13px}.empty h3{margin:0;font-size:17px}.empty p{max-width:720px}.tp-client-panel footer{display:flex;gap:9px;align-items:flex-start;font-size:10px;line-height:1.7;color:#9d8bab;border-top:1px solid #ffffff14;padding-top:16px}.tp-client-panel footer :global(svg){flex-shrink:0}@media(max-width:1050px){.client-summary{grid-template-columns:1fr}.client-controls{grid-template-columns:1fr}.tp-client-panel{padding:18px}.actions button.remove{margin-left:0}}
</style>
